arguments.command:
cd /src/mruby && python - <<'PY'
from pathlib import Path
path = Path('mrbgems/mruby-bigint/core/bigint.c')
text = path.read_text()
old = """static int
mpz_get_int(mpz_t *y, mrb_int *v)
{
  mp_limb i;

  if (y->sn == 0) {
    i = 0;
  }
  else if (digits(y) > 2 || y->p[1] > 1) {
    return FALSE;
  }
  else {
    i = (y->sn * (y->p[0] | (y->p[1] & 1) << DIGITBITS));
    if (MRB_INT_MAX < i || i < MRB_INT_MIN) return FALSE;
  }
  *v = i;
  return TRUE;
}
"""
new = """static int
mpz_get_int(mpz_t *y, mrb_int *v)
{
  mp_limb i;

  if (y->sn == 0) {
    i = 0;
  }
  else {
    /*
     * mpz values can be represented with a single allocated limb (sz==1).
     * Access limb[1] only through the bounds-checked accessor.
     */
    const size_t d = digits(y);
    const mp_limb hi = dg(y, 1);

    if (d > 2 || hi > 1) {
      return FALSE;
    }

    i = (y->sn * (dg(y, 0) | ((hi & 1) << DIGITBITS)));
    if (MRB_INT_MAX < i || i < MRB_INT_MIN) return FALSE;
  }
  *v = i;
  return TRUE;
}
"""
if old not in text:
    raise SystemExit('Expected block not found; file may have changed')
path.write_text(text.replace(old, new))
print('patched', path)
PY
